/**
 * Which clusters DocBits can actually fix — DOCB-14318.
 *
 * Measured on dev (org FELLOWPRO AG, 02.09.2026): three of the six clusters a
 * bulk AI run covered — 71 documents across XSD position CII, IBAN checksum
 * and XSD header — carry `potential_pure_lift_pct = 0`. Zero lift is not a
 * small number, it is a statement: not one of those documents becomes
 * touchless through anything the customer changes in DocBits. The supplier
 * has to correct the electronic document and send it again.
 *
 * On screen those three sat indistinguishably beside the clusters that ARE a
 * setting away from being fixed, each carrying a "What to change" section that
 * reads like there is a screen to open. A clerk working the list top to bottom
 * spends a morning on three things they cannot do.
 *
 * This module is the SINGLE client-side answer to "can we fix this one?", and
 * it deliberately mirrors the backend's
 * `module/automation_intelligence/advisor/selection.py::
 * supplier_only_expression` clause for clause. The backend counts the split
 * for the button's tooltip and this file draws it; two rules would be a
 * tooltip that says "3 fixable" over a list showing four.
 */

import type { TouchlessBulkResultEntry } from './touchless-bulk-results';

/**
 * The fixability code the backend uses for "the inbound document itself is
 * malformed" — an e-invoice that fails its own XSD. Nothing in DocBits
 * repairs that; the sender has to reissue it.
 */
export const SUPPLIER_ACTION_FIXABILITY = 'SUPPLIER_ACTION';

/** The shape this decision needs. Both members optional — see below. */
export interface FixabilityFacts {
  fixability_code?: string | null;
  potential_pure_lift_pct?: number | null;
}

/**
 * Whether a cluster is one only the supplier can act on.
 *
 * Two independent routes to the same conclusion, because either alone leaves
 * a gap:
 *
 *  * a **measured** lift of zero or less — the number says no document here
 *    is recoverable inside DocBits;
 *  * `fixability_code === 'SUPPLIER_ACTION'` — the classification says the
 *    same thing about a cluster whose lift has not been computed.
 *
 * An **unmeasured** lift (`null`, or the field missing entirely) is
 * deliberately NOT caught. "Not computed yet" is a different claim from
 * "computed at zero", and treating them alike would file every freshly
 * clustered issue — and every result row whose cluster read has not landed —
 * under "nothing you can do", which is a claim the client cannot make.
 */
export function isSupplierOnlyCluster(facts: FixabilityFacts): boolean {
  if (facts.fixability_code === SUPPLIER_ACTION_FIXABILITY) return true;
  const lift = facts.potential_pure_lift_pct;
  return typeof lift === 'number' && Number.isFinite(lift) && lift <= 0;
}

/** The same decision for a bulk result row, whose fields are already flattened. */
export function isSupplierOnlyEntry(entry: TouchlessBulkResultEntry): boolean {
  return isSupplierOnlyCluster({
    fixability_code: entry.fixabilityCode,
    potential_pure_lift_pct: entry.liftPct,
  });
}

export interface BulkResultSplit {
  fixable: TouchlessBulkResultEntry[];
  supplierOnly: TouchlessBulkResultEntry[];
  fixableCount: number;
  supplierOnlyCount: number;
}

/**
 * The result list, cut into its two headings.
 *
 * Stable within each group: the server ordered the run fixable-first and by
 * leverage inside that, and a list that re-sorted would stop matching the
 * order the analyses actually ran in.
 */
export function splitBulkResultEntries(
  entries: TouchlessBulkResultEntry[],
): BulkResultSplit {
  const fixable: TouchlessBulkResultEntry[] = [];
  const supplierOnly: TouchlessBulkResultEntry[] = [];
  for (const entry of entries) {
    (isSupplierOnlyEntry(entry) ? supplierOnly : fixable).push(entry);
  }
  return {
    fixable,
    supplierOnly,
    fixableCount: fixable.length,
    supplierOnlyCount: supplierOnly.length,
  };
}
