/**
 * Naming the supplier a cluster belongs to — DOCB-14333.
 *
 * The backend files every document whose supplier could not be resolved into
 * one bucket, keyed by the literal string `"unknown"`
 * (`module/automation_intelligence/constants.py::UNKNOWN_SUPPLIER_KEY`), and
 * it puts that same string in the `supplier_name` column. Rendered verbatim —
 * which is what the result list, the supplier table and the cluster card all
 * did — it reads as a bug, and on dev it is not a corner case: 249 of the
 * org's 251 lost documents sit in that bucket (DOCB-14319).
 *
 * Two things follow, and they are the whole of this module. The bucket has to
 * be RECOGNISED before it can be named, and a large one has to be reported as
 * what it actually is: supplier recognition not working, which is a touchless
 * blocker in its own right rather than a label on a row.
 *
 * Pure functions, no i18n: the wording belongs to the components (they have
 * `$t`), the decision belongs here (so four of them cannot disagree about it).
 */

/** The bucket's key, verbatim from the backend. */
export const UNRESOLVED_SUPPLIER_KEY = 'unknown';

/**
 * At what share of the lost documents the bucket stops being a row and starts
 * being a finding (DOCB-14333).
 *
 * Half. Below that the unattributed documents are a tail worth naming
 * honestly on their own row; at or above it, the supplier dimension of the
 * whole report is unreliable and saying so is more useful than any per-row
 * label.
 */
export const UNRESOLVED_SUPPLIER_FINDING_PCT = 50;

function clean(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

/**
 * Whether this cluster/row is the unattributed bucket rather than a supplier.
 *
 * Checks the KEY for the bucket and treats a missing key as unresolved too —
 * a row with nothing to identify it is not a supplier either, and rendering it
 * blank hides the same fact the literal string shouted.
 *
 * The name is only consulted when it is EXACTLY the bucket string, because
 * that is the backend echoing its own key. A real supplier called "Unknown
 * Tools Ltd" keeps its name.
 */
export function isUnresolvedSupplier(
  supplierKey: unknown,
  supplierName?: unknown,
): boolean {
  const key = clean(supplierKey).toLowerCase();
  if (!key || key === UNRESOLVED_SUPPLIER_KEY) return true;
  return clean(supplierName).toLowerCase() === UNRESOLVED_SUPPLIER_KEY;
}

export interface TouchlessUnresolvedShare {
  /** Lost documents nobody could attribute to a supplier. */
  unresolved: number;
  /** Lost documents in the window, attributed or not. */
  total: number;
  /** 0-100, or null when there is no denominator to divide by. */
  pct: number | null;
  /** Whether this is big enough to report as a finding of its own. */
  isFinding: boolean;
}

function count(value: unknown): number {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 0) return 0;
  return Math.floor(parsed);
}

/**
 * How much of the window's loss has no supplier behind it (DOCB-14333).
 *
 * Read off the supplier rows the panel already has, so the hint counts the
 * same population the table shows rather than a second query that could
 * disagree with it.
 *
 * An empty window answers `pct: null` and `isFinding: false`: a 0/0 share is
 * not 100 %, and a hint that fires on every org with no losses is a hint
 * nobody reads.
 */
export function unresolvedSupplierShare(
  rows: ReadonlyArray<Record<string, unknown> | null | undefined> | null,
): TouchlessUnresolvedShare {
  let unresolved = 0;
  let total = 0;
  for (const row of rows ?? []) {
    if (!row || typeof row !== 'object') continue;
    const lost = count(row.lost_docs);
    if (!lost) continue;
    total += lost;
    if (isUnresolvedSupplier(row.supplier_key, row.supplier_name)) {
      unresolved += lost;
    }
  }
  const pct = total > 0 ? (unresolved / total) * 100 : null;
  return {
    unresolved,
    total,
    pct,
    isFinding: pct !== null && pct >= UNRESOLVED_SUPPLIER_FINDING_PCT,
  };
}
