/**
 * The `change_proposal` contract, as the UI reads it — DOCB-14325.
 *
 * One recommendation, one structure, two consumers: this dashboard and the MCP
 * tools. Everything that decides WHAT would change — the settings family, the
 * identifier, the value, and whether it may be written at all — is decided by
 * the backend and only rendered here. A client that resolved a target of its
 * own would be the second recommendation path the design exists to prevent,
 * and the two would eventually disagree about what DocBits is changing on a
 * customer's tenant.
 *
 * Kept out of the store and out of the component for the usual reason: the
 * mapping from "an untyped JSON body" to "the fields a template binds" is the
 * part worth testing directly, and neither Pinia nor a mounted card should
 * have to exist to test it.
 */

/**
 * What a reader may DO with a proposal.
 *
 *  * `applicable` — target and value are both known; preview and apply work.
 *  * `needs_identification` — the settings family is certain, the identifier
 *    or the value is not. Carries `open_questions` instead of a guess.
 *  * `not_applicable` — the fix is not ours to make (a supplier has to change
 *    what they send). Carried rather than omitted so the card can say WHY
 *    there is no button.
 *
 * Typed as a union PLUS `string`: the backend owns this vocabulary and may add
 * to it, and an unknown status must degrade to "no button" rather than blank
 * the explanation the reader came for.
 */
export type TouchlessProposalStatus =
  | 'applicable'
  | 'needs_identification'
  | 'not_applicable';

export type TouchlessProposalRiskLevel = 'low' | 'medium' | 'high';

/** The kind of editor the proposed value needs. */
export type TouchlessProposalValueKind = 'boolean' | 'number' | 'text';

export interface TouchlessProposalScope {
  org_id: string;
  sub_org_id: string | null;
}

/** WHAT would change: a family, its identifiers, and the one setting. */
export interface TouchlessProposalTarget {
  family: string;
  doc_type: string | null;
  sub_doc_type: string | null;
  field_name: string | null;
  rule: string | null;
  object_key: string | null;
  /** Null while the target is not identified — never a plausible stand-in. */
  setting: string | null;
  scope: TouchlessProposalScope | null;
}

/** WHAT the result would be, with the denominator it was measured over. */
export interface TouchlessProposalEffect {
  documents_in_window: number;
  window_days: number;
  projected_lift_pp: number | null;
  confidence: number | null;
  basis: string;
}

/** WHAT could go wrong. Never omitted by the schema, never empty. */
export interface TouchlessProposalRisk {
  level: TouchlessProposalRiskLevel | string;
  what_could_go_wrong: string;
  compliance_note: string | null;
}

/** The four questions, and exactly the four. */
export interface TouchlessProposalExplanation {
  analysis: string;
  why_it_matters: string;
  expected_result: string;
  what_changes: string;
}

export interface TouchlessProposalApplySpec {
  /** Null means there is nothing to call — and so nothing to offer. */
  endpoint: string | null;
  dry_run_supported: boolean;
}

export interface TouchlessChangeProposal {
  proposal_id: string;
  issue_signature: string;
  status: TouchlessProposalStatus | string;
  target: TouchlessProposalTarget;
  current_value: unknown;
  proposed_value: unknown;
  expected_effect: TouchlessProposalEffect;
  risk: TouchlessProposalRisk;
  reversible: boolean;
  owner: string;
  explanation: TouchlessProposalExplanation;
  open_questions: string[];
  provenance: string;
  apply: TouchlessProposalApplySpec;
}

/**
 * The four questions, in the order the PO asks them, each with the Tolgee key
 * of its label.
 *
 * A list rather than four bindings in the template: the order IS the argument
 * — what is happening, why it matters, what it buys, what it costs — and a
 * template that hard-codes it four times is one edit away from asking them in
 * a different order on a different screen.
 */
export const PROPOSAL_QUESTION_KEYS: ReadonlyArray<{
  field: keyof TouchlessProposalExplanation;
  labelKey: string;
}> = [
  { field: 'analysis', labelKey: 'touchless_proposal_q_analysis' },
  { field: 'why_it_matters', labelKey: 'touchless_proposal_q_why' },
  { field: 'expected_result', labelKey: 'touchless_proposal_q_result' },
  { field: 'what_changes', labelKey: 'touchless_proposal_q_changes' },
];

function toText(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function toOptionalText(value: unknown): string | null {
  const text = toText(value);
  return text ? text : null;
}

function toCount(value: unknown): number {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 0) return 0;
  return Math.floor(parsed);
}

/** A finite number, or null — never a 0 standing in for "not sent". */
function toRate(value: unknown): number | null {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function normalizeScope(value: unknown): TouchlessProposalScope | null {
  const raw = asRecord(value);
  const orgId = toText(raw.org_id);
  if (!orgId) return null;
  return { org_id: orgId, sub_org_id: toOptionalText(raw.sub_org_id) };
}

function normalizeTarget(value: unknown): TouchlessProposalTarget {
  const raw = asRecord(value);
  return {
    family: toText(raw.family),
    doc_type: toOptionalText(raw.doc_type),
    sub_doc_type: toOptionalText(raw.sub_doc_type),
    field_name: toOptionalText(raw.field_name),
    rule: toOptionalText(raw.rule),
    object_key: toOptionalText(raw.object_key),
    setting: toOptionalText(raw.setting),
    scope: normalizeScope(raw.scope),
  };
}

function normalizeEffect(value: unknown): TouchlessProposalEffect {
  const raw = asRecord(value);
  return {
    documents_in_window: toCount(raw.documents_in_window),
    window_days: toCount(raw.window_days) || 30,
    projected_lift_pp: toRate(raw.projected_lift_pp),
    confidence: toRate(raw.confidence),
    basis: toText(raw.basis),
  };
}

function normalizeRisk(value: unknown): TouchlessProposalRisk {
  const raw = asRecord(value);
  return {
    level: toText(raw.level) || 'medium',
    what_could_go_wrong: toText(raw.what_could_go_wrong),
    compliance_note: toOptionalText(raw.compliance_note),
  };
}

/**
 * The explanation, or null when it is not the four-field block.
 *
 * A proposal that cannot say what it changes is not a proposal, and half an
 * explanation rendered under four headings reads as three answers the backend
 * declined to give rather than as a malformed payload.
 */
function normalizeExplanation(
  value: unknown,
): TouchlessProposalExplanation | null {
  const raw = asRecord(value);
  const explanation = {
    analysis: toText(raw.analysis),
    why_it_matters: toText(raw.why_it_matters),
    expected_result: toText(raw.expected_result),
    what_changes: toText(raw.what_changes),
  };
  const complete = PROPOSAL_QUESTION_KEYS.every(
    ({ field }) => explanation[field].length > 0,
  );
  return complete ? explanation : null;
}

function normalizeApply(value: unknown): TouchlessProposalApplySpec {
  const raw = asRecord(value);
  return {
    endpoint: toOptionalText(raw.endpoint),
    dry_run_supported: raw.dry_run_supported === true,
  };
}

function normalizeOne(value: unknown): TouchlessChangeProposal | null {
  const raw = asRecord(value);
  const proposalId = toText(raw.proposal_id);
  if (!proposalId) return null;
  const explanation = normalizeExplanation(raw.explanation);
  if (!explanation) return null;

  return {
    proposal_id: proposalId,
    issue_signature: toText(raw.issue_signature),
    status: toText(raw.status) || 'not_applicable',
    target: normalizeTarget(raw.target),
    current_value: 'current_value' in raw ? raw.current_value : null,
    proposed_value: 'proposed_value' in raw ? raw.proposed_value : null,
    expected_effect: normalizeEffect(raw.expected_effect),
    risk: normalizeRisk(raw.risk),
    reversible: raw.reversible === true,
    owner: toText(raw.owner) || 'customer',
    explanation,
    open_questions: Array.isArray(raw.open_questions)
      ? raw.open_questions.map(toText).filter(Boolean)
      : [],
    provenance: toText(raw.provenance),
    apply: normalizeApply(raw.apply),
  };
}

/**
 * The proposals in a `GET /issues/{sig}/change-proposals` body.
 *
 * Three shapes are accepted because two of them have been in flight for this
 * endpoint and a bare list is what a caller naturally passes from a test.
 * Reading only one would blank the whole block against a backend that sends
 * another — and the block is the answer the reader came for.
 *
 * A malformed member is dropped, never the list around it.
 */
export function normalizeChangeProposals(
  payload: unknown,
): TouchlessChangeProposal[] {
  const raw = Array.isArray(payload)
    ? payload
    : Array.isArray(asRecord(payload).change_proposals)
      ? (asRecord(payload).change_proposals as unknown[])
      : Array.isArray(asRecord(payload).proposals)
        ? (asRecord(payload).proposals as unknown[])
        : [];

  const proposals: TouchlessChangeProposal[] = [];
  for (const entry of raw) {
    const proposal = normalizeOne(entry);
    if (proposal) proposals.push(proposal);
  }
  return proposals;
}

/**
 * Whether this proposal may be previewed and applied from the card.
 *
 * Three conditions, all of them the backend's own: the status says the target
 * is resolved, the owner is somebody inside this organisation, and there is an
 * endpoint to call. The schema already refuses to give a supplier-owned
 * proposal an endpoint — the owner check is here anyway, because the cost of
 * the belt is one line and the cost of the braces failing is an Apply button
 * over a change the customer cannot make.
 */
export function isApplyOffered(
  proposal: TouchlessChangeProposal | null | undefined,
): boolean {
  if (!proposal) return false;
  if (proposal.status !== 'applicable') return false;
  if (proposal.owner === 'supplier') return false;
  return Boolean(proposal.apply.endpoint);
}

/**
 * The editor the proposed value needs.
 *
 * Read from the CURRENT value first — it is what the setting actually holds,
 * so it is the authority on the setting's type — and from the proposed value
 * when the setting has never been written (`current_value: null` is a real
 * state, not a missing one).
 */
export function proposalValueKind(
  proposal: TouchlessChangeProposal | null | undefined,
): TouchlessProposalValueKind {
  const sample =
    proposal?.current_value === null || proposal?.current_value === undefined
      ? proposal?.proposed_value
      : proposal.current_value;
  if (typeof sample === 'boolean') return 'boolean';
  if (typeof sample === 'number' && Number.isFinite(sample)) return 'number';
  return 'text';
}

/**
 * The biggest lift among the proposals somebody can actually press.
 *
 * Deliberately not the biggest lift full stop: an unresolved 99 pp proposal is
 * a lead, not a gain, and putting it in a results list beside a button would
 * promise the reader something they cannot collect.
 */
export function highestApplicableLift(
  proposals: readonly TouchlessChangeProposal[] | null | undefined,
): number | null {
  let best: number | null = null;
  for (const proposal of proposals ?? []) {
    if (!isApplyOffered(proposal)) continue;
    const lift = proposal.expected_effect.projected_lift_pp;
    if (lift === null) continue;
    if (best === null || lift > best) best = lift;
  }
  return best;
}
