/**
 * Turning a bulk advisor run into something a reader can look at — DOCB-14311.
 *
 * The run itself is a list of sha256 signatures and a map of outcomes
 * (`TouchlessBulkRun`, see `touchless-advice.ts`). That is enough to count
 * "3/6" and nothing else: it cannot say which SUPPLIERS were analysed, how big
 * their clusters are, or what the analysis was worth. The panel therefore
 * reads each dispatched cluster once and keeps the handful of fields a result
 * row needs; these are the pure functions that shape and combine the two.
 *
 * Kept out of the store on purpose — the mapping from "an outcome map plus a
 * summary map" to "the rows on screen" is the part worth testing directly, and
 * the store should not have to be instantiated to test it.
 */

import type { TouchlessBulkRun } from './touchless-advice';

/**
 * The parts of `GET /issues/{signature}` a result row shows.
 *
 * Deliberately NOT the whole cluster: keeping the response object would tie a
 * list that outlives the run to a payload the run is still mutating, and the
 * four fields the ticket asks for (supplier, title, affected documents, lift)
 * are all that is ever rendered here.
 */
export interface TouchlessBulkClusterSummary {
  signature: string;
  /** The route param the "open" link travels with. '' when unknown. */
  supplierKey: string;
  /** What the row is called. '' until the cluster read has landed. */
  supplierName: string;
  /** Both halves of the card's headline, translated at render time. */
  stage: string | null;
  reasonCode: string;
  /**
   * What KIND of change would fix it (DOCB-14318). Carried because the row
   * has to be filed under "Fixable in DocBits" or "Supplier action only", and
   * `SUPPLIER_ACTION` is one of the two things that decide it — see
   * `touchless-fixability.ts`. `''` while the cluster read has not landed.
   */
  fixabilityCode: string;
  affectedDocCount: number;
  /** Percentage POINTS, as everywhere in this feature. Null when unknown. */
  liftPct: number | null;
}

/**
 * How one dispatched cluster is doing.
 *
 * `queued` and `running` are the SERVER's own two words for "not finished"
 * (DOCB-14327). They used to be collapsed into one, on the grounds that the
 * poll could not tell them apart — which stopped being true when the batched
 * status route started answering `pending` / `running` per signature. Measured
 * on dev, a six-cluster run spends eighty seconds moving through those states
 * one cluster at a time, and collapsing them left every row identical for the
 * whole of it. `running` remains the fallback for a backend that says nothing.
 *
 * `cached` is `done` that cost nothing — the run touched the row and
 * `generated_at` never moved. Worth its own word because a five-second run
 * and an eighty-second one otherwise look exactly alike (DOCB-14312).
 *
 * `unknown` is what `running` becomes once the run is no longer being watched
 * (DOCB-14327). It is not a failure and must not be drawn as one: the worker
 * may still be going. It says this tab stopped following the run — which is
 * exactly what a chip reading "Running" for ever refused to say.
 */
export type TouchlessBulkResultStatus =
  | 'queued'
  | 'running'
  | 'cached'
  | 'done'
  | 'error'
  | 'unknown';

export interface TouchlessBulkResultEntry extends TouchlessBulkClusterSummary {
  status: TouchlessBulkResultStatus;
  /**
   * The biggest lift this cluster offers through a proposal somebody can
   * actually press (DOCB-14325), or null when it offers none.
   *
   * Deliberately separate from `liftPct`: that one is what the whole CLUSTER
   * is worth if its cause goes away, which includes causes only a supplier can
   * fix. Putting that number beside a button would promise the reader a gain
   * they cannot collect.
   */
  applicableLiftPct: number | null;
}

/** A non-negative integer from an untyped JSON field, or 0. */
function toCount(value: unknown): number {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 0) return 0;
  return Math.floor(parsed);
}

/** A finite number, or null — never a 0 standing in for "not sent". */
function toRate(value: unknown): number | null {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

/** A trimmed string, or ''. */
function toText(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

/**
 * The row-sized view of one `/issues/{signature}` read.
 *
 * Every field is defensive: the read crosses the network, and a cluster whose
 * supplier name did not arrive must still be listed (as its signature's row
 * with a blank name) rather than drop out of a list whose whole purpose is to
 * account for every dispatched analysis.
 */
export function summarizeBulkCluster(
  signature: string,
  cluster: Record<string, unknown> | null | undefined,
): TouchlessBulkClusterSummary {
  return {
    signature,
    supplierKey: toText(cluster?.supplier_key),
    supplierName: toText(cluster?.supplier_name),
    stage: toText(cluster?.stage) || null,
    reasonCode: toText(cluster?.reason_code),
    fixabilityCode: toText(cluster?.fixability_code),
    affectedDocCount: toCount(cluster?.affected_doc_count),
    liftPct: toRate(cluster?.potential_pure_lift_pct),
  };
}

/** A row for a signature whose cluster read has not landed (or failed). */
function placeholderSummary(signature: string): TouchlessBulkClusterSummary {
  return {
    signature,
    supplierKey: '',
    supplierName: '',
    stage: null,
    reasonCode: '',
    fixabilityCode: '',
    affectedDocCount: 0,
    liftPct: null,
  };
}

/**
 * The rows on screen: one per dispatched signature, in the server's order.
 *
 * Driven by `run.signatures` and never by the summary map, so the list is
 * always exactly what the 202 promised — a cluster whose metadata read failed
 * still appears, still carries its state, and simply has nothing to say about
 * itself yet.
 */
export function buildBulkResultEntries(
  run: TouchlessBulkRun | null,
  summaries: Record<string, TouchlessBulkClusterSummary>,
  applicableLifts: Record<string, number | null> = {},
): TouchlessBulkResultEntry[] {
  if (!run) return [];
  // DOCB-14327. The phase decides what an ABSENT outcome means, and it has to:
  // a signature with no outcome on a run still being watched is genuinely
  // running, and the same signature on a run this tab has given up on is a
  // cluster nobody here knows anything about. Rendering both as "Running" is
  // what left the reporter's screen spinning at 0/6 indefinitely.
  const watching = run.phase === 'running';
  const cached = new Set(run.cachedSignatures ?? []);
  return run.signatures.map((signature) => {
    const outcome = run.outcomes[signature];
    return {
      ...(summaries[signature] ?? placeholderSummary(signature)),
      applicableLiftPct: applicableLifts[signature] ?? null,
      status: rowStatus(
        outcome,
        run.states?.[signature],
        cached.has(signature),
        watching,
      ),
    };
  });
}

/**
 * One row's state, from the ending if there is one and the server's own word
 * if there is not.
 *
 * The ending always wins: a status read that lands after the run was given up
 * on must not put a row back into a state nobody is watching any more.
 */
function rowStatus(
  outcome: 'completed' | 'failed' | undefined,
  serverState: string | undefined,
  isCached: boolean,
  watching: boolean,
): TouchlessBulkResultStatus {
  if (outcome === 'failed') return 'error';
  if (outcome === 'completed') return isCached ? 'cached' : 'done';
  if (!watching) return 'unknown';
  if (serverState === 'pending') return 'queued';
  return 'running';
}
