/**
 * Timers are module-level, NOT state: a `setTimeout` handle in Pinia state is
 * neither serialisable nor meaningfully reactive, and devtools would try to
 * clone it on every mutation.
 */
const advicePollTimers = new Map<string, ReturnType<typeof setTimeout>>();
let adviceClockTimer: ReturnType<typeof setInterval> | null = null;

/**
 * The bulk run's single read-back timer. One for the whole run, not one per
 * signature: the poll reads the pending signatures together on each tick, so
 * eight clusters cost eight requests every five seconds rather than eight
 * independent, drifting schedules.
 */
let bulkPollTimer: ReturnType<typeof setTimeout> | null = null;

/**
 * Whether this tab is in the background (DOCB-14315).
 *
 * A backgrounded tab still runs its timers, so before this the indicator kept
 * spending requests on a screen nobody could see — and a dashboard left open
 * in a second tab doubled the bill for a run the reader started once. The tick
 * still FIRES while hidden (the schedule must not be lost, the worker keeps
 * going, and the run still has to be seen to end); it simply asks for nothing
 * until the tab comes forward.
 *
 * Guarded because the store is also loaded in a `node` test environment and
 * during SSR, where there is no `document` at all.
 */
function isTabHidden(): boolean {
  return typeof document !== 'undefined' && document.hidden === true;
}

function clearBulkPollTimer(): void {
  if (bulkPollTimer !== null) {
    clearTimeout(bulkPollTimer);
    bulkPollTimer = null;
  }
}

function clearAdvicePollTimer(signature: string): void {
  const timer = advicePollTimers.get(signature);
  if (timer !== undefined) {
    clearTimeout(timer);
    advicePollTimers.delete(signature);
  }
}

/** Period presets offered by the filter bar. Values are backend `period` values. */
export const TOUCHLESS_PERIOD_OPTIONS = ['7d', '30d', '90d'] as const;

export type TouchlessPeriod =
  | (typeof TOUCHLESS_PERIOD_OPTIONS)[number]
  | string;

/**
 * Phase A filter dimensions: period + doc type.
 *
 * Supplier is deliberately NOT a filter. Narrowing the whole dashboard to one
 * supplier would make the headline rate mean something different from the
 * number the same page shows elsewhere; the supplier view is a drill-down
 * (queue row click → diagnosis page), not a filter of the aggregate.
 */
export interface TouchlessFilters {
  period: TouchlessPeriod;
  doc_type: string | null;
}

/** Independently loadable sections of the dashboard. */
export type TouchlessSection = 'summary' | 'trend' | 'suppliers';

export interface TouchlessPagination {
  page: number;
  rowsPerPage: number;
  sortBy: string;
  descending: boolean;
}

export const DEFAULT_TOUCHLESS_FILTERS: TouchlessFilters = {
  period: '30d',
  doc_type: null,
};

export const DEFAULT_TOUCHLESS_PAGINATION: TouchlessPagination = {
  page: 1,
  rowsPerPage: 25,
  sortBy: 'recoverable_docs',
  descending: true,
};

/**
 * Daily points get unreadable past ~30 days, so long periods are bucketed
 * weekly. Kept as a pure function so the chart and the store agree.
 */
export function intervalForPeriod(period: TouchlessPeriod): 'day' | 'week' {
  const days = Number.parseInt(String(period), 10);
  return Number.isFinite(days) && days > 30 ? 'week' : 'day';
}

/**
 * Everything the card needs to know about ONE proposal in flight
 * (DOCB-14325).
 *
 * `edited` and `preview` together are the Apply gate. A preview token is bound
 * server-side to the value it previewed, so an edit has to throw the preview
 * away — otherwise the reader would press Apply on a value nothing has dry-run
 * and get a 409 they cannot interpret.
 */
export interface TouchlessProposalState {
  proposalId: string;
  signature: string;
  /** The proposed value as it stands, edited or not. */
  editedValue: unknown;
  /** Whether the reader has changed it since the last preview. */
  edited: boolean;
  previewing: boolean;
  preview: TouchlessChangePreviewResult | null;
  previewOutcome: TouchlessPreviewOutcome | null;
  previewError: string | null;
  applying: boolean;
  applyOutcome: TouchlessApplyOutcome | null;
  applyError: string | null;
  /** The outcome row's id, once a change has actually been written. */
  changeId: string | null;
  outcome: TouchlessChangeOutcomeResult | null;
  reverting: boolean;
  reverted: boolean;
}

/** A proposal nobody has touched yet: the backend's value, no preview. */
function freshProposalState(
  proposal: TouchlessChangeProposal,
): TouchlessProposalState {
  return {
    proposalId: proposal.proposal_id,
    signature: proposal.issue_signature,
    editedValue: proposal.proposed_value,
    edited: false,
    previewing: false,
    preview: null,
    previewOutcome: null,
    previewError: null,
    applying: false,
    applyOutcome: null,
    applyError: null,
    changeId: null,
    outcome: null,
    reverting: false,
    reverted: false,
  };
}

export const useTouchlessIntelligenceStore = defineStore(
  'touchless_intelligence',
  {
    state: () => ({
      loading: false,

      /**
       * Monotonic request generation PER SECTION. A section commits its
       * response (and clears its own loading flag) only while its own token is
       * still current.
       *
       * Per-section rather than global: with one shared counter, a retry or a
       * pagination click in one section would invalidate every other section's
       * in-flight request, and those requests' current-only finalizers would
       * then never run — leaving their loading flags stuck true forever.
       * Sections must only ever invalidate themselves; `loadAll` and
       * `setFilters` invalidate all of them together, which is correct because
       * they genuinely supersede every section at once.
       */
      generations: { summary: 0, trend: 0, suppliers: 0 } as Record<
        TouchlessSection,
        number
      >,

      // Shared filters (period + doc_type — Phase A dimensions)
      filters: { ...DEFAULT_TOUCHLESS_FILTERS } as TouchlessFilters,

      // Pagination for the supplier opportunity queue. Kept here (not in the
      // table component) because changing a filter must reset it.
      supplierPagination: {
        ...DEFAULT_TOUCHLESS_PAGINATION,
      } as TouchlessPagination,

      // GET /summary
      summary: null as TouchlessSummaryResponse | null,
      summaryLoading: false,
      summaryError: false,

      // GET /trend
      trend: null as TouchlessTrendResponse | null,
      trendLoading: false,
      trendError: false,

      // GET /suppliers/opportunities (server-paged)
      suppliers: [] as TouchlessSupplierOpportunity[],
      supplierCount: 0,
      suppliersLoading: false,
      suppliersError: false,

      /**
       * Advisor runs, keyed by issue signature.
       *
       * In the STORE and not in IssueClusterCard on purpose: the card unmounts
       * whenever the reader scrolls the list out of the DOM, navigates to a
       * document trace and back, or switches supplier — and a 40-second job
       * whose only record of itself lives in that component would be forgotten
       * every time. Keyed by signature rather than by supplier so two cards
       * can run at once without either one showing the other's spinner.
       */
      adviceRuns: {} as Record<string, TouchlessAdviceRun>,

      /**
       * `Date.now()` for the elapsed readouts, advanced once a second while at
       * least one run is active. One clock for every card: a per-card interval
       * would tick N times a second and drift the numbers apart.
       */
      adviceClock: 0,

      /**
       * The bulk run started from the overview's "Analyse N clusters" button,
       * or null when none is being watched (DOCB-14285).
       *
       * Exactly one at a time: the button is disabled while a run is active, so
       * there is never a second one to keep apart. Deliberately NOT persisted —
       * a reload simply loses the indicator, which is honest, because the run
       * itself belongs to the worker and the reloaded table already shows how
       * far it got. Persisting it would mean resurrecting a run this tab never
       * started and could not have finished watching.
       */
      bulkRun: null as TouchlessBulkRun | null,

      /**
       * The last run's own list, kept after `bulkRun` is cleared (DOCB-14311).
       *
       * The run's END is exactly when the reader needs the list most, and it
       * is also when the panel drops `bulkRun` so the button becomes clickable
       * and the "x/N" disappears. Two fields rather than one flag on the run:
       * "is a run being watched" and "what did the last run cover" are
       * genuinely different questions, and collapsing them is what would put a
       * finished run back in charge of the button.
       */
      bulkResultsRun: null as TouchlessBulkRun | null,

      /**
       * Signature -> the handful of cluster fields a result row shows.
       *
       * Read once per dispatched cluster rather than kept from the progress
       * poll: that poll belongs to the run's lifecycle and reads only the
       * advice STATUS, and a list that has to survive the run cannot depend on
       * a tick that has stopped happening.
       */
      bulkClusterSummaries: {} as Record<string, TouchlessBulkClusterSummary>,

      /**
       * Change proposals per issue signature (DOCB-14325).
       *
       * Read once per cluster and kept here rather than on the card: the card
       * is an expansion item that unmounts whenever the reader scrolls the
       * list, and a preview token whose only record lived there would be lost
       * — turning the mandatory dry run into a dry run the reader has to
       * repeat every time they look away.
       */
      changeProposals: {} as Record<string, TouchlessChangeProposal[]>,
      changeProposalsLoading: {} as Record<string, boolean>,
      changeProposalsError: {} as Record<string, string | null>,

      /**
       * The preview/apply state of ONE proposal, keyed by `proposal_id`.
       *
       * Per proposal and not per cluster: a cluster can carry more than one,
       * and a shared token would let a preview of the first be spent applying
       * the second.
       */
      proposalStates: {} as Record<string, TouchlessProposalState>,
    }),

    getters: {
      /**
       * Pure Touchless target in percent, as reported by the API. Falls back to
       * the documented default only while no trend has loaded or when the
       * backend sends no usable number.
       */
      targetPct(): number {
        return resolveTargetPct(this.trend?.target);
      },

      /**
       * Pure Touchless rate in percent (0-100), or null when there is none.
       *
       * `?? 0` here made the tiles read "0%" for an org whose documents are
       * all still in flight — and it did so THROUGH the null-aware formatter,
       * because the coercion happened first. "No terminal documents yet" and
       * "nothing ran touchless" are different statements and the dashboard has
       * to be able to tell them apart.
       */
      purePct(): number | null {
        return this.summary?.official_touchless_rate?.pure_pct ?? null;
      },

      /** AP Touchless rate in percent (0-100), or null when there is none. */
      apPct(): number | null {
        return this.summary?.official_touchless_rate?.ap_pct ?? null;
      },

      /**
       * Signed distance of the Pure rate from the org target, in points.
       * Null when there is no rate: a distance from an unknown value is not 0,
       * it is unknown, and rendering -70 pp would invent a failure.
       */
      pureDeltaPct(): number | null {
        const pure = this.purePct;
        return pure === null ? null : pure - this.targetPct;
      },

      bucketCount(): (bucket: string) => number {
        return (bucket: string) => this.summary?.buckets?.[bucket]?.count ?? 0;
      },

      /**
       * A bucket's share of the rate denominator, or null when it has none.
       * IN_PROGRESS and NOT_ELIGIBLE are not in that denominator, so they
       * always answer null — never 0.
       */
      bucketPct(): (bucket: string) => number | null {
        return (bucket: string) => this.summary?.buckets?.[bucket]?.pct ?? null;
      },

      /** First blocking stages, largest share first. */
      blockingStages(): TouchlessBlockingStage[] {
        const stages = this.summary?.first_blocking_stages ?? [];
        return [...stages].sort((a, b) => (b.count ?? 0) - (a.count ?? 0));
      },

      /** Documents whose loss could not be attributed to a known reason. */
      undiagnosedCount(): number {
        return (this.summary?.first_blocking_stages ?? [])
          .filter((stage) => (stage.reason_code || 'UNKNOWN') === 'UNKNOWN')
          .reduce((sum, stage) => sum + (stage.count ?? 0), 0);
      },

      /** Documents whose loss has a concrete reason code. */
      diagnosedCount(): number {
        return (this.summary?.first_blocking_stages ?? [])
          .filter((stage) => (stage.reason_code || 'UNKNOWN') !== 'UNKNOWN')
          .reduce((sum, stage) => sum + (stage.count ?? 0), 0);
      },

      /** Share of blocked documents with a concrete reason code, in percent. */
      diagnosedPct(): number {
        const diagnosed = this.diagnosedCount;
        const total = diagnosed + this.undiagnosedCount;
        if (total <= 0) return 0;
        return Math.round((diagnosed / total) * 100);
      },

      docTypeOptions(): TouchlessDocTypeOption[] {
        return this.summary?.available_filters?.doc_types ?? [];
      },

      /** Freshness stamp shown by MetricContractFooter. */
      dataAsOf(): string {
        return this.summary?.data_as_of || this.trend?.data_as_of || '';
      },

      metricContractVersion(): string {
        return (
          this.summary?.metric_contract_version ||
          this.trend?.metric_contract_version ||
          ''
        );
      },

      /** The run for one cluster, or null — what IssueClusterCard is given. */
      adviceRunFor(): (signature: string) => TouchlessAdviceRun | null {
        return (signature: string) => this.adviceRuns[signature] ?? null;
      },

      /** The "x" in "x/N fertig" — dispatched analyses that have ended. */
      /** "1:18" while a run is being watched, '' otherwise (DOCB-14327). */
      bulkRunElapsedLabel(): string {
        if (!this.bulkRun || this.bulkRun.phase !== 'running') return '';
        return formatElapsedClock(
          bulkRunElapsedSeconds(this.bulkRun, this.adviceClock || Date.now()),
        );
      },

      bulkRunDone(): number {
        return bulkRunDoneCount(this.bulkRun);
      },

      /** The "N" — what the SERVER said it dispatched, not what is on screen. */
      bulkRunTotal(): number {
        return bulkRunTotal(this.bulkRun);
      },

      /** Ended-but-failed analyses. They count toward "x"; they still failed. */
      bulkRunFailed(): number {
        return bulkRunFailedCount(this.bulkRun);
      },

      /**
       * Analyses this run served from the cache without recomputing anything
       * (DOCB-14312) — the number that lets the completion toast say
       * "already analysed, no new computation" only when it is true.
       */
      bulkRunCached(): number {
        return bulkRunCachedCount(this.bulkRun);
      },

      /** Whether a bulk run is still being watched — the button's disable. */
      isBulkRunActive(): boolean {
        return this.bulkRun?.phase === 'running';
      },

      /**
       * The analysed clusters, in the order the server dispatched them
       * (DOCB-14311).
       *
       * Prefers the LIVE run, so the same list carries the reader from "these
       * six are running" to "these six were analysed" without ever being
       * rebuilt; falls back to the finished run's snapshot once the live one
       * has been cleared. Empty when nothing has been dispatched in this tab,
       * which is what keeps the list off screen entirely.
       */
      bulkResultEntries(): TouchlessBulkResultEntry[] {
        const run = this.bulkRun ?? this.bulkResultsRun;
        const lifts: Record<string, number | null> = {};
        for (const signature of run?.signatures ?? []) {
          lifts[signature] = highestApplicableLift(
            this.changeProposals[signature] ?? [],
          );
        }
        return buildBulkResultEntries(run, this.bulkClusterSummaries, lifts);
      },

      /** Whether the elapsed clock still has anything to count for. */
      /** A cluster's proposals, biggest lift first as the server ordered them. */
      changeProposalsFor(): (signature: string) => TouchlessChangeProposal[] {
        return (signature: string) => this.changeProposals[signature] ?? [];
      },

      /**
       * The state of one proposal, or a neutral one.
       *
       * Never null: the card binds to these fields directly, and an optional
       * chain in every binding is how a template starts disagreeing with
       * itself about whether "no preview yet" means disabled or hidden.
       */
      proposalStateFor(): (proposalId: string) => TouchlessProposalState {
        return (proposalId: string) =>
          this.proposalStates[proposalId] ?? {
            proposalId,
            signature: '',
            editedValue: null,
            edited: false,
            previewing: false,
            preview: null,
            previewOutcome: null,
            previewError: null,
            applying: false,
            applyOutcome: null,
            applyError: null,
            changeId: null,
            outcome: null,
            reverting: false,
            reverted: false,
          };
      },

      /**
       * Whether Apply may be pressed at all.
       *
       * A fresh, unedited, unspent preview token — and nothing else. This is
       * the same rule the server enforces; having it here too means the button
       * is dead rather than the refusal arriving as a 409 the reader has to
       * decode.
       */
      canApplyProposal(): (proposalId: string) => boolean {
        return (proposalId: string) => {
          const state = this.proposalStates[proposalId];
          if (!state) return false;
          if (state.edited) return false;
          if (state.applying || state.changeId) return false;
          return Boolean(state.preview?.previewToken);
        };
      },

      /**
       * The biggest lift a cluster offers that somebody can actually press
       * (DOCB-14311/14325). Null when nothing on it is applicable.
       */
      applicableLiftFor(): (signature: string) => number | null {
        return (signature: string) =>
          highestApplicableLift(this.changeProposals[signature] ?? []);
      },

      hasActiveAdviceRun(): boolean {
        // Annotated because Pinia's getter `this` widens the record's value
        // type to `unknown` while the surrounding getters are still inferring.
        const runs: TouchlessAdviceRun[] = Object.values(this.adviceRuns);
        return runs.some((run) => isAdviceRunActive(run.phase));
      },
    },

    actions: {
      /** Opens a new request generation for ONE section and returns its id. */
      beginSectionGeneration(section: TouchlessSection): number {
        this.generations[section] += 1;
        return this.generations[section];
      },

      isCurrentGeneration(
        section: TouchlessSection,
        generation: number,
      ): boolean {
        return generation === this.generations[section];
      },

      /**
       * Invalidates every section at once — used when the whole page is being
       * replaced (a filter change, or a fresh loadAll).
       */
      beginAllGenerations(): Record<TouchlessSection, number> {
        const next = {} as Record<TouchlessSection, number>;
        (Object.keys(this.generations) as TouchlessSection[]).forEach(
          (section) => {
            next[section] = this.beginSectionGeneration(section);
          },
        );
        return next;
      },

      /**
       * Replace part of the shared filter set and reset the supplier queue back
       * to page 1 — a filtered result set has a different length, so keeping the
       * old offset would show an empty or misaligned page. Any response still in
       * flight for the previous filters is invalidated here.
       */
      setFilters(patch: Partial<TouchlessFilters>): void {
        this.filters = { ...this.filters, ...patch };
        this.resetPagination();
        this.beginAllGenerations();
      },

      resetPagination(): void {
        this.supplierPagination = {
          ...this.supplierPagination,
          page: 1,
        };
      },

      resetFilters(): void {
        this.filters = { ...DEFAULT_TOUCHLESS_FILTERS };
        this.supplierPagination = { ...DEFAULT_TOUCHLESS_PAGINATION };
        this.beginAllGenerations();
      },

      async loadAll(): Promise<void> {
        const generations = this.beginAllGenerations();
        this.loading = true;
        try {
          // Each section reports its own failure through its error flag AND
          // rejects, so `allSettled` can tell a partial outage (page stays
          // usable) from a total one (page-level error state).
          const results = await Promise.allSettled([
            this.loadSummary(generations.summary),
            this.loadTrend(generations.trend),
            this.loadSuppliers(generations.suppliers),
          ]);

          const failures = results.filter((r) => r.status === 'rejected');
          if (failures.length > 0) {
            console.warn(
              `[Touchless] ${failures.length}/${results.length} dashboard calls failed:`,
              failures.map((f) => (f as PromiseRejectedResult).reason),
            );
          }

          if (failures.length === results.length) {
            throw new Error('All touchless dashboard data calls failed');
          }
        } finally {
          // The page-level spinner belongs to the round that started it; a
          // section superseded meanwhile must not leave it spinning.
          if (
            this.isCurrentGeneration('summary', generations.summary) ||
            this.isCurrentGeneration('trend', generations.trend) ||
            this.isCurrentGeneration('suppliers', generations.suppliers)
          ) {
            this.loading = false;
          }
        }
      },

      async loadSummary(
        generation: number = this.beginSectionGeneration('summary'),
      ): Promise<void> {
        this.summaryLoading = true;
        this.summaryError = false;
        try {
          const result = await touchlessService.getSummary(
            this.filters.period,
            this.filters.doc_type || undefined,
          );
          // A newer filter selection has already superseded this request.
          if (!this.isCurrentGeneration('summary', generation)) return;

          if (!isValidSummaryResponse(result)) {
            throw new Error('Malformed touchless summary response');
          }
          this.summary = result;
        } catch (error) {
          if (this.isCurrentGeneration('summary', generation)) {
            // Drop the stale numbers: a failed reload under new filters must
            // not leave the previous period's KPIs on screen looking current.
            this.summary = null;
            this.summaryError = true;
          }
          throw error;
        } finally {
          if (this.isCurrentGeneration('summary', generation)) {
            this.summaryLoading = false;
          }
        }
      },

      async loadTrend(
        generation: number = this.beginSectionGeneration('trend'),
      ): Promise<void> {
        this.trendLoading = true;
        this.trendError = false;
        try {
          const result = await touchlessService.getTrend(
            this.filters.period,
            intervalForPeriod(this.filters.period),
            this.filters.doc_type || undefined,
          );
          if (!this.isCurrentGeneration('trend', generation)) return;

          if (!isValidTrendResponse(result)) {
            throw new Error('Malformed touchless trend response');
          }
          this.trend = result;
        } catch (error) {
          if (this.isCurrentGeneration('trend', generation)) {
            this.trend = null;
            this.trendError = true;
          }
          throw error;
        } finally {
          if (this.isCurrentGeneration('trend', generation)) {
            this.trendLoading = false;
          }
        }
      },

      /**
       * Server-paged supplier opportunity queue. Offset is derived from the
       * stored page so the request and the table can never disagree about which
       * slice is on screen.
       */
      async loadSuppliers(
        generation: number = this.beginSectionGeneration('suppliers'),
      ): Promise<void> {
        this.suppliersLoading = true;
        this.suppliersError = false;
        const { page, rowsPerPage, sortBy, descending } =
          this.supplierPagination;
        try {
          const result = await touchlessService.getSupplierOpportunities({
            offset: (page - 1) * rowsPerPage,
            limit: rowsPerPage,
            order_by_field: sortBy,
            order_by_direction: descending ? 'desc' : 'asc',
            period: this.filters.period,
            doc_type: this.filters.doc_type,
          });
          if (!this.isCurrentGeneration('suppliers', generation)) return;

          if (!isValidSupplierListResponse(result)) {
            throw new Error('Malformed touchless supplier page');
          }
          this.suppliers = result.data;
          this.supplierCount = result.element_count;
        } catch (error) {
          if (this.isCurrentGeneration('suppliers', generation)) {
            // An empty table with a stale row count would let the pager offer
            // pages that no longer exist.
            this.suppliers = [];
            this.supplierCount = 0;
            this.suppliersError = true;
          }
          throw error;
        } finally {
          if (this.isCurrentGeneration('suppliers', generation)) {
            this.suppliersLoading = false;
          }
        }
      },

      /** Table sort change: back to page 1, then refetch. */
      async setSupplierSort(
        sortBy: string,
        descending: boolean,
      ): Promise<void> {
        this.supplierPagination = {
          ...this.supplierPagination,
          sortBy,
          descending,
          page: 1,
        };
        await this.loadSuppliers(this.beginSectionGeneration('suppliers'));
      },

      /** Table page / page-size change: refetch that slice. */
      async setSupplierPage(page: number, rowsPerPage: number): Promise<void> {
        this.supplierPagination = {
          ...this.supplierPagination,
          page,
          rowsPerPage,
        };
        await this.loadSuppliers(this.beginSectionGeneration('suppliers'));
      },

      // ======================================================================
      // Advisor runs
      // ======================================================================

      /** Replaces one run record; never mutates in place, so watchers fire. */
      putAdviceRun(
        signature: string,
        patch: Partial<TouchlessAdviceRun>,
      ): void {
        const current = this.adviceRuns[signature];
        if (!current) return;
        this.adviceRuns = {
          ...this.adviceRuns,
          [signature]: { ...current, ...patch },
        };
      },

      /**
       * Ticks `adviceClock` every second, but only while something is running.
       * A permanently running interval would keep the whole dashboard
       * re-rendering on an idle tab for no reader-visible reason.
       */
      startAdviceClock(): void {
        this.adviceClock = Date.now();
        if (adviceClockTimer !== null) return;
        adviceClockTimer = setInterval(() => {
          this.adviceClock = Date.now();
          if (!this.hasActiveAdviceRun && !this.isBulkRunActive) {
            this.stopAdviceClock();
          }
        }, 1000);
      },

      stopAdviceClock(): void {
        if (adviceClockTimer !== null) {
          clearInterval(adviceClockTimer);
          adviceClockTimer = null;
        }
      },

      /**
       * Start (or restart) the advisor for one cluster.
       *
       * `currentAdvice` is the advice block the card is rendering RIGHT NOW; it
       * becomes the baseline the poll compares against. Passing it in rather
       * than re-reading it means the comparison is against what the reader
       * actually saw when they clicked.
       */
      async startAdviceGeneration(
        signature: string,
        currentAdvice: TouchlessAdvice | null = null,
      ): Promise<void> {
        if (!signature) return;
        // Click-spam is already harmless server-side (the claim is taken by the
        // route, so a second request dispatches nothing), but a second local
        // run would reset the elapsed clock the reader is watching.
        if (isAdviceRunActive(this.adviceRuns[signature]?.phase)) return;

        clearAdvicePollTimer(signature);
        this.adviceRuns = {
          ...this.adviceRuns,
          [signature]: {
            signature,
            phase: 'dispatching',
            startedAt: Date.now(),
            attempts: 0,
            message: null,
            advice: null,
            baseline: adviceFingerprint(currentAdvice),
          },
        };
        this.startAdviceClock();

        try {
          const result = await touchlessService.generateAdvice(signature, {
            window: TOUCHLESS_ADVICE_WINDOW_DAYS,
          });
          // The run was cleared (reset, or a newer one took over) while the
          // POST was in flight — nothing left to report to.
          if (!this.adviceRuns[signature]) return;

          switch (result.outcome) {
            case 'ready':
              // Nothing was spent and nothing dispatched: the server already
              // had an answer for this evidence. Show it immediately — unless
              // the block is malformed, in which case saying "finished" over
              // unchanged content would claim an answer that is not there.
              if (isValidAdvice(result.advice)) {
                this.putAdviceRun(signature, {
                  phase: 'ready',
                  advice: result.advice,
                  message: null,
                });
              } else {
                this.putAdviceRun(signature, {
                  phase: 'unavailable',
                  message: result.message,
                });
              }
              break;
            case 'running':
              this.putAdviceRun(signature, { phase: 'running', message: null });
              this.scheduleAdvicePoll(signature);
              return;
            case 'disabled':
              this.putAdviceRun(signature, {
                phase: 'disabled',
                message: result.message,
              });
              break;
            case 'forbidden':
              this.putAdviceRun(signature, {
                phase: 'forbidden',
                message: result.message,
              });
              break;
            case 'not_found':
              this.putAdviceRun(signature, {
                phase: 'not_found',
                message: result.message,
              });
              break;
            default:
              this.putAdviceRun(signature, {
                phase: 'unavailable',
                message: result.message,
              });
          }
        } catch (error) {
          // A model outage must cost the EXPLANATION, never the diagnosis, so
          // this ends as a quiet hint beside the card's own content.
          console.warn(
            `[Touchless] advice generation failed for ${signature}:`,
            error,
          );
          if (this.adviceRuns[signature]) {
            this.putAdviceRun(signature, {
              phase: 'failed',
              message: messageFromError(error),
            });
          }
        }
        if (!this.hasActiveAdviceRun) this.stopAdviceClock();
      },

      scheduleAdvicePoll(signature: string): void {
        clearAdvicePollTimer(signature);
        advicePollTimers.set(
          signature,
          setTimeout(() => {
            advicePollTimers.delete(signature);
            void this.pollAdviceOnce(signature);
          }, TOUCHLESS_ADVICE_POLL_INTERVAL_MS),
        );
      },

      /**
       * One read-back of the cluster the reader is looking at.
       *
       * Reads `/issues/{signature}` rather than reloading the whole supplier
       * diagnosis: the poll must touch ONE card. Re-reading the diagnosis every
       * three seconds would flip the page's loading flag and put every other
       * cluster into a skeleton for a job that concerns none of them.
       */
      async pollAdviceOnce(signature: string): Promise<void> {
        const run = this.adviceRuns[signature];
        if (!run || !isAdviceRunActive(run.phase)) return;

        const attempts = run.attempts + 1;
        this.putAdviceRun(signature, { phase: 'reading', attempts });

        let advice: TouchlessAdvice | null = null;
        try {
          const result = await touchlessService.getIssueCluster(
            signature,
            TOUCHLESS_ADVICE_WINDOW_DAYS,
          );
          const candidate = result?.cluster?.advice ?? null;
          advice = isValidAdvice(candidate) ? candidate : null;
        } catch (error) {
          // A failed READ is not a failed generation. The job may well be
          // finishing; swallow it and try again on the next tick.
          console.warn(
            `[Touchless] advice poll read failed for ${signature}:`,
            error,
          );
        }

        // Reset / supplier change happened mid-read.
        if (!this.adviceRuns[signature]) return;

        if (advice && adviceFingerprint(advice) !== run.baseline) {
          const lastError =
            typeof advice.last_error === 'string' && advice.last_error.trim()
              ? advice.last_error
              : null;
          if (lastError) {
            this.putAdviceRun(signature, {
              phase: 'failed',
              advice,
              message: lastError,
            });
          } else {
            this.putAdviceRun(signature, {
              phase: 'ready',
              advice,
              message: null,
            });
          }
          if (!this.hasActiveAdviceRun) this.stopAdviceClock();
          return;
        }

        if (attempts >= TOUCHLESS_ADVICE_MAX_POLLS) {
          // NOT an error: the job may still land. The card says "still
          // running, look again in a moment" and offers another read.
          this.putAdviceRun(signature, { phase: 'timeout', message: null });
          if (!this.hasActiveAdviceRun) this.stopAdviceClock();
          return;
        }

        this.putAdviceRun(signature, { phase: 'running' });
        this.scheduleAdvicePoll(signature);
      },

      /**
       * Watch clusters a run that happened ELSEWHERE already dispatched —
       * DOCB-14337.
       *
       * The supplier diagnosis page starts one server-side run over all of a
       * supplier's clusters and is handed back the signatures the workers
       * really took. Those clusters need run records so their cards render
       * progress and results, but they must NOT be re-dispatched:
       * `startAdviceGeneration` would POST once more per cluster, which the
       * server refuses anyway and which would reset the elapsed clock the
       * reader is watching.
       *
       * So this is `startAdviceGeneration` minus the POST: seed the record in
       * `running`, take the baseline from the advice the card is showing right
       * now, and hand each signature to the same poll loop every other run
       * uses.
       */
      adoptAdviceRuns(
        runs: { signature: string; advice?: TouchlessAdvice | null }[],
      ): void {
        const adopted: string[] = [];
        const next = { ...this.adviceRuns };
        (runs || []).forEach((entry) => {
          const signature = entry?.signature;
          if (!signature) return;
          // A cluster already being watched keeps its own clock: the reader
          // may have started it by hand a moment ago.
          if (isAdviceRunActive(next[signature]?.phase)) return;
          next[signature] = {
            signature,
            phase: 'running',
            startedAt: Date.now(),
            attempts: 0,
            message: null,
            advice: null,
            baseline: adviceFingerprint(entry.advice ?? null),
          };
          adopted.push(signature);
        });
        if (!adopted.length) return;

        this.adviceRuns = next;
        this.startAdviceClock();
        adopted.forEach((signature) => this.scheduleAdvicePoll(signature));
      },

      /**
       * Resume polling an existing run — for the "look again" button after a
       * timeout. Deliberately does NOT re-POST: the job is already claimed
       * server-side, and a second dispatch would only be refused.
       */
      resumeAdvicePolling(signature: string): void {
        const run = this.adviceRuns[signature];
        if (!run || isAdviceRunActive(run.phase)) return;
        this.putAdviceRun(signature, {
          phase: 'running',
          attempts: 0,
          message: null,
        });
        this.startAdviceClock();
        void this.pollAdviceOnce(signature);
      },

      /** Drops one run record and its timer (used on retry and in teardown). */
      clearAdviceRun(signature: string): void {
        clearAdvicePollTimer(signature);
        if (!this.adviceRuns[signature]) return;
        const next = { ...this.adviceRuns };
        delete next[signature];
        this.adviceRuns = next;
        if (!this.hasActiveAdviceRun) this.stopAdviceClock();
      },

      resetAdviceRuns(): void {
        advicePollTimers.forEach((timer) => clearTimeout(timer));
        advicePollTimers.clear();
        this.stopAdviceClock();
        this.adviceRuns = {};
      },

      // ======================================================================
      // Bulk run progress (DOCB-14285)
      // ======================================================================

      /**
       * Start watching the run the server just acknowledged.
       *
       * `signatures` is the 202's own list, so "N" is what the WORKER was
       * handed rather than what the preview guessed a moment earlier. An empty
       * list — an older backend, or a dispatch that started nothing — means no
       * indicator at all: a 0/0 that can never move is worse than the toast on
       * its own.
       */
      startBulkAdviceRun(
        signatures: string[],
        dispatchedAt: string | null = null,
        startedAt = Date.now(),
        runId: string | null = null,
      ): void {
        clearBulkPollTimer();
        if (!signatures.length) {
          this.bulkRun = null;
          return;
        }
        this.bulkRun = {
          signatures: [...signatures],
          phase: 'running',
          startedAt,
          dispatchedAt,
          // DOCB-14327. The server's own handle for this run, sent back on
          // every status read so the answer describes the run the worker was
          // given rather than one rebuilt from this tab's context.
          runId,
          // Nothing has happened yet, so the stall ceiling starts at the
          // click and moves forward every time the counter does.
          lastProgressAt: startedAt,
          outcomes: {},
          states: {},
          // Filled in from the run's own read-backs (DOCB-14312), never from
          // the dispatch's pre-flight expectation: what the toast claims at
          // the END has to be what actually happened.
          cachedSignatures: [],
        };
        // The elapsed readout ticks for a bulk run too (DOCB-14327): a run at
        // "2/6" after fifteen seconds and the same "2/6" after nine minutes
        // are different situations, and the counter alone cannot say which.
        this.startAdviceClock();
        // DOCB-14328. Written down before the first tick, not after the run
        // ends: leaving the page a second after the click is exactly the case
        // this exists for, and a run only recorded on completion would lose
        // the one the reader most wants back.
        storeBulkRun(this.bulkRun);
        // A new run is a new thing to read; whatever was discarded before is
        // no longer the run this panel is about.
        markBulkRunDismissed(null);
        // The list belongs to the run, and it is what a restore rebuilds.
        this.bulkResultsRun = { ...this.bulkRun, outcomes: {} };
        this.scheduleBulkAdvicePoll();
      },

      /**
       * Put the last bulk run back on screen (DOCB-14328).
       *
       * Called when the panel mounts. The server's record is the source —
       * only it can say whether a run is still going, because only it can see
       * the worker — and this browser's own copy is the fallback for a record
       * that has expired or a cache that is unreachable.
       *
       * A restore never STARTS anything and never fails a mount: every kind
       * of absence, and every kind of failure, is "there is nothing to put
       * back".
       */
      async restoreBulkRun(): Promise<void> {
        // A run this tab is already watching outranks anything stored: it is
        // the same run, with fresher progress.
        if (this.bulkRun) return;

        let latest: Awaited<
          ReturnType<typeof touchlessService.getLatestBulkRun>
        > | null = null;
        try {
          latest = await touchlessService.getLatestBulkRun();
        } catch (error) {
          console.warn('[Touchless] bulk run restore failed:', error);
        }

        if (
          latest &&
          latest.status === 'ready' &&
          latest.signatures.length &&
          // The reader discarded exactly this run. The server still has it —
          // it keeps its record for a day — so without this the "Discard"
          // button would look broken on the very next mount.
          !isBulkRunDismissed(latest.runId)
        ) {
          const outcomes: Record<string, TouchlessBulkOutcome> = {};
          const cachedSignatures: string[] = [];
          // DOCB-14327's per-cluster states come back with the run, so a
          // restored one draws queued/running rows straight away instead of
          // six identical chips until the next tick lands.
          const states: Record<string, TouchlessBulkStatusValue> = {};
          for (const entry of latest.statuses ?? []) {
            if (!entry?.signature) continue;
            const state = bulkStatusValue(entry.status);
            if (state) states[entry.signature] = state;
            const outcome = bulkStatusOutcome(entry.status);
            if (outcome) outcomes[entry.signature] = outcome;
            if (entry.cached === true) cachedSignatures.push(entry.signature);
          }
          const restored: TouchlessBulkRun = {
            signatures: [...latest.signatures],
            // Only the server may call a run still running.
            phase: latest.complete ? 'done' : 'running',
            // This browser never saw the click, so the clock starts now — the
            // stall ceiling then gives a resumed run its own ten minutes
            // rather than declaring it dead on arrival.
            startedAt: Date.now(),
            lastProgressAt: Date.now(),
            dispatchedAt: latest.dispatchedAt,
            runId: latest.runId,
            outcomes,
            cachedSignatures,
            states,
          };
          if (latest.complete) {
            // Finished: the list, immediately. Nothing is watched, and no
            // second request stands between the mount and the rows.
            this.bulkResultsRun = restored;
          } else {
            // Still going: resume against the SAME dispatch, keeping the
            // progress it has already made so the counter does not restart.
            clearBulkPollTimer();
            this.bulkRun = restored;
            this.bulkResultsRun = { ...restored };
            this.scheduleBulkAdvicePoll();
          }
          storeBulkRun(restored);
          void this.loadBulkClusterSummaries(restored.signatures);
          return;
        }

        // The server has nothing. This browser might.
        const kept = readStoredBulkRun();
        if (!kept) return;
        this.bulkResultsRun = kept;
        void this.loadBulkClusterSummaries(kept.signatures);
      },

      /**
       * "Discard" — the reader is done with this list (DOCB-14328).
       *
       * Deliberately also forgets the stored run, which is what separates it
       * from `clearBulkResults`: that one is teardown and a restore is meant
       * to undo it, this one is a decision and a restore must respect it.
       */
      dismissBulkResults(): void {
        markBulkRunDismissed(
          this.bulkRun?.runId ?? this.bulkResultsRun?.runId ?? null,
        );
        clearBulkPollTimer();
        this.bulkRun = null;
        this.bulkResultsRun = null;
        this.bulkClusterSummaries = {};
        clearStoredBulkRun();
      },

      /**
       * Arm the next status read, at the cadence the run's own age asks for
       * (DOCB-14315): 5 s for the first minute, 10 s after that.
       */
      scheduleBulkAdvicePoll(): void {
        clearBulkPollTimer();
        const run = this.bulkRun;
        const elapsed = run ? Date.now() - run.startedAt : 0;
        bulkPollTimer = setTimeout(() => {
          bulkPollTimer = null;
          void this.pollBulkAdviceOnce();
        }, bulkPollIntervalFor(elapsed));
      },

      /**
       * ONE read-back covering every signature that has not ended yet
       * (DOCB-14315).
       *
       * This used to fan out `GET /issues/{signature}` per pending signature,
       * which is what made a 6-cluster run cost 112 requests in 81 s: that
       * route is per-cluster, and each call also pages the affected-document
       * ledger for a caller that wants one bit back per cluster. The whole run
       * now fits in `GET /issues/advice/bulk-status`, so the poll's cost stops
       * scaling with the fan-out's size.
       *
       * The supplier table is still refreshed ONCE, when the run ends, so the
       * reader is not watching rows flicker through a skeleton every five
       * seconds for a job most of whose clusters are not even on this page.
       *
       * A read that throws is not a finished analysis. It is swallowed and
       * retried on the next tick, exactly as the single-issue poll does — the
       * worker is very likely still going, and marking a signature terminal
       * because one GET failed would end the run early and refresh a table
       * that has nothing new in it.
       */
      async pollBulkAdviceOnce(): Promise<void> {
        const run = this.bulkRun;
        if (!run || run.phase !== 'running') return;

        const pending = bulkRunPendingSignatures(run);

        // Nobody is looking. Keep the schedule (the worker is still going and
        // the run has to be seen to end) but spend nothing on it.
        if (isTabHidden()) {
          this.scheduleBulkAdvicePoll();
          return;
        }

        let reads: {
          outcomes: Record<string, TouchlessBulkOutcome>;
          cached: string[];
          states: Record<string, TouchlessBulkStatusValue>;
        } | null = null;
        try {
          reads = await this.readBulkAdviceStatuses(
            pending,
            run.dispatchedAt,
            run.runId ?? null,
          );
        } catch (error) {
          console.warn('[Touchless] bulk status read failed:', error);
        }

        // The run was reset (panel unmounted, or a filter change) while the
        // read was in flight — there is nothing left to report into.
        if (this.bulkRun !== run) return;

        const outcomes: Record<string, TouchlessBulkOutcome> = {
          ...run.outcomes,
          ...(reads?.outcomes ?? {}),
        };
        // A set, so a signature read back twice cannot inflate the count the
        // completion toast reports (DOCB-14312).
        const cachedSignatures = [
          ...new Set([
            ...(run.cachedSignatures ?? []),
            ...(reads?.cached ?? []),
          ]),
        ];
        // DOCB-14327. "Progress" is the counter moving, not a tick happening:
        // a read that comes back with the same six pending signatures is
        // exactly the situation the stall ceiling exists to catch.
        const moved =
          Object.keys(outcomes).length > Object.keys(run.outcomes).length;
        this.bulkRun = {
          ...run,
          outcomes,
          cachedSignatures,
          states: { ...(run.states ?? {}), ...(reads?.states ?? {}) },
          lastProgressAt: moved ? Date.now() : bulkRunLastProgressAt(run),
        };

        // DOCB-14328: the kept copy tracks the run, so a navigation mid-run
        // restores what the counter had reached rather than what it started at.
        storeBulkRun(this.bulkRun);

        if (isBulkRunComplete(this.bulkRun)) {
          this.finishBulkAdviceRun('done');
          return;
        }
        if (isBulkRunStalled(this.bulkRun, Date.now())) {
          // Ten minutes without the counter moving. The worker may still be
          // going — this tab simply has no evidence of it any more, and the
          // rows say "unknown" instead of pretending to still be watching.
          this.finishBulkAdviceRun('stalled');
          return;
        }
        if (isBulkRunExpired(this.bulkRun, Date.now())) {
          // NOT a failure: the worker may still be going. Watching stops and
          // the toast says how far it got, which is all this tab can honestly
          // claim to know.
          this.finishBulkAdviceRun('timeout');
          return;
        }
        this.scheduleBulkAdvicePoll();
      },

      /**
       * The terminal signatures out of one status read (DOCB-14315).
       *
       * Prefers the batched route, and falls back to the per-cluster read it
       * replaced when the backend does not have it. That fallback is not
       * theoretical: the API ships ahead of the Web, but a rollback would
       * otherwise freeze the indicator at 0/N with no way for it ever to
       * advance — slow and correct beats fast and stuck.
       */
      async readBulkAdviceStatuses(
        pending: string[],
        dispatchedAt: string | null,
        runId: string | null = null,
      ): Promise<{
        outcomes: Record<string, TouchlessBulkOutcome>;
        cached: string[];
        states: Record<string, TouchlessBulkStatusValue>;
      }> {
        const outcomes: Record<string, TouchlessBulkOutcome> = {};
        const cached: string[] = [];
        // DOCB-14327: the server's own word per signature, kept alongside the
        // endings so the rows can say "queued" and "running" rather than one
        // blue chip for both.
        const states: Record<string, TouchlessBulkStatusValue> = {};
        if (!pending.length) return { outcomes, cached, states };

        const payload = await touchlessService.getBulkAdviceStatus(
          pending,
          dispatchedAt,
          TOUCHLESS_ADVICE_WINDOW_DAYS,
          runId,
        );

        if (payload?.supported) {
          for (const entry of payload.statuses ?? []) {
            if (!entry?.signature) continue;
            const state = bulkStatusValue(entry.status);
            if (state) states[entry.signature] = state;
            const outcome = bulkStatusOutcome(entry.status);
            if (!outcome) continue;
            outcomes[entry.signature] = outcome;
            // DOCB-14312. The backend PROVED this one was served from the
            // cache: it touched the row and `generated_at` never moved.
            if (entry.cached === true) cached.push(entry.signature);
          }
          return { outcomes, cached, states };
        }

        // Pre-DOCB-14315 backend: the read-back the ticket removed, kept only
        // as the degraded path. One request per pending signature, and the
        // `updated_at` vs `dispatched_at` comparison made here rather than
        // server-side.
        const settled = await Promise.allSettled(
          pending.map((signature) =>
            touchlessService
              .getIssueCluster(signature, TOUCHLESS_ADVICE_WINDOW_DAYS)
              .then((result) => ({
                signature,
                outcome: bulkAdviceOutcome(
                  {
                    status: result?.cluster?.advice?.status,
                    updatedAt: result?.cluster?.advice?.updated_at,
                  },
                  dispatchedAt,
                ),
              })),
          ),
        );
        for (const entry of settled) {
          if (entry.status !== 'fulfilled') continue;
          if (entry.value.outcome) {
            outcomes[entry.value.signature] = entry.value.outcome;
          }
        }
        // The per-cluster read cannot tell a cache hit from a fresh
        // generation — that is one of the things the batched route added — so
        // this path claims nothing rather than guessing. It cannot separate
        // queued from running either, which is why `running` stays the
        // fallback for a row with no server state.
        return { outcomes, cached, states };
      },

      /**
       * End the run and pull the table forward.
       *
       * The refresh is the whole point of the feature: the reason a bulk run
       * was worth watching is that the supplier rows flip out of
       * NEEDS_DIAGNOSIS when it lands, and before this the only way to see that
       * was to reload the page by hand. It is fired for `timeout` as well as
       * `done` — a partial run still diagnosed some of the rows on screen.
       *
       * `loadSuppliers` rejects on failure so `loadAll` can tell a partial
       * outage from a total one; here the table's own error flag is already the
       * user-visible answer, so the rejection is absorbed rather than left to
       * surface as an unhandled promise from a timer callback.
       */
      finishBulkAdviceRun(phase: 'done' | 'timeout' | 'stalled'): void {
        clearBulkPollTimer();
        if (!this.bulkRun) return;
        this.bulkRun = { ...this.bulkRun, phase };
        // So a reader who comes back tomorrow finds the run as it ENDED, not
        // as it looked on its last tick (DOCB-14328).
        storeBulkRun(this.bulkRun);
        void this.loadSuppliers().catch(() => {
          // suppliersError already drives the table's error state.
        });
      },

      /**
       * Read the clusters a run covers, so they can be NAMED (DOCB-14311).
       *
       * One read per signature, fired once when the run starts and once when
       * it ends — not on every poll tick. The progress poll deliberately reads
       * only the advice status; this is the other half, and separating them
       * means the list can be refreshed after the run has stopped being
       * watched at all.
       *
       * `allSettled`, and a read that throws simply leaves that row without
       * metadata: a cluster whose GET failed still belongs in a list whose job
       * is to account for every dispatched analysis.
       */
      async loadBulkClusterSummaries(signatures: string[]): Promise<void> {
        const wanted = signatures.filter(Boolean);
        if (!wanted.length) return;
        const settled = await Promise.allSettled(
          wanted.map((signature) =>
            touchlessService
              .getIssueCluster(signature, TOUCHLESS_ADVICE_WINDOW_DAYS)
              .then((result) =>
                summarizeBulkCluster(
                  signature,
                  result?.cluster as unknown as Record<string, unknown>,
                ),
              ),
          ),
        );
        const next = { ...this.bulkClusterSummaries };
        for (const entry of settled) {
          if (entry.status !== 'fulfilled') continue;
          next[entry.value.signature] = entry.value;
        }
        this.bulkClusterSummaries = next;

        // The proposals beside them (DOCB-14325), so each row can name the
        // biggest lift that is actually pressable. All-settled and unawaited
        // by the caller for the same reason the summaries are: a cluster whose
        // proposals cannot be read still gets its row.
        await Promise.allSettled(
          wanted.map((signature) => this.loadChangeProposals(signature)),
        );
      },

      /**
       * Keep the run that just ended, before the watcher lets go of it.
       *
       * A copy, not the same object: `resetBulkAdviceRun` is about to null
       * `bulkRun`, and the outcomes map is what turns each row into
       * done/error rather than a permanent "running".
       */
      snapshotBulkResults(): void {
        if (!this.bulkRun) return;
        this.bulkResultsRun = {
          ...this.bulkRun,
          outcomes: { ...this.bulkRun.outcomes },
        };
      },

      /** Re-read the finished run's clusters, so the rows show final numbers. */
      async refreshBulkResultSummaries(): Promise<void> {
        await this.loadBulkClusterSummaries(
          this.bulkResultsRun?.signatures ?? [],
        );
      },

      /**
       * Forget the last run's list — a filter change (the eligible set moved)
       * and panel teardown. Separate from `resetBulkAdviceRun` because the
       * completion watcher needs the run gone and the list kept.
       */
      clearBulkResults(): void {
        this.bulkResultsRun = null;
        this.bulkClusterSummaries = {};
      },

      /**
       * Stop watching and forget the run — panel teardown, and any filter
       * change that moves the page to a different window.
       *
       * Clearing the timer BEFORE dropping the state matters: a tick that fires
       * after the panel unmounted would re-read eight clusters for a screen
       * nobody is looking at.
       */
      resetBulkAdviceRun(): void {
        clearBulkPollTimer();
        this.bulkRun = null;
      },
      // ── change proposals (DOCB-14325) ──────────────────────────────────

      /**
       * Read one cluster's change proposals.
       *
       * A failed read leaves the rest of the card exactly as it was: the
       * cause, the evidence and the fix steps are computed from recorded
       * pipeline evidence and are correct whether or not this endpoint
       * answers. Blanking them because a proposal read failed would cost the
       * reader the diagnosis to save them a button.
       *
       * States already in flight are kept across a re-read: a preview the
       * reader ran ten seconds ago is still the preview they are looking at,
       * and dropping it would silently close Apply under their cursor.
       */
      async loadChangeProposals(
        signature: string,
        options: { force?: boolean } = {},
      ): Promise<void> {
        if (!signature) return;
        if (!options.force && this.changeProposals[signature]) return;
        if (this.changeProposalsLoading[signature]) return;

        this.changeProposalsLoading = {
          ...this.changeProposalsLoading,
          [signature]: true,
        };
        this.changeProposalsError = {
          ...this.changeProposalsError,
          [signature]: null,
        };

        try {
          const response = await touchlessService.getChangeProposals(
            signature,
            TOUCHLESS_ADVICE_WINDOW_DAYS,
          );
          const proposals = normalizeChangeProposals(response);
          this.changeProposals = {
            ...this.changeProposals,
            [signature]: proposals,
          };
          const states = { ...this.proposalStates };
          for (const proposal of proposals) {
            if (!states[proposal.proposal_id]) {
              states[proposal.proposal_id] = freshProposalState(proposal);
            }
          }
          this.proposalStates = states;
        } catch (error) {
          this.changeProposals = {
            ...this.changeProposals,
            [signature]: this.changeProposals[signature] ?? [],
          };
          this.changeProposalsError = {
            ...this.changeProposalsError,
            [signature]:
              messageFromError(error) ?? 'touchless_proposal_load_failed',
          };
        } finally {
          this.changeProposalsLoading = {
            ...this.changeProposalsLoading,
            [signature]: false,
          };
        }
      },

      /** Merge a patch into one proposal's state, or do nothing if it is gone. */
      putProposalState(
        proposalId: string,
        patch: Partial<TouchlessProposalState>,
      ): void {
        const current = this.proposalStates[proposalId];
        if (!current) return;
        this.proposalStates = {
          ...this.proposalStates,
          [proposalId]: { ...current, ...patch },
        };
      },

      /**
       * The reader edited the proposed value.
       *
       * Throws the preview away, which is the whole point: the token the
       * server issued is bound to the value it previewed, so keeping it would
       * let an unpreviewed value ride a valid-looking token. The refusal would
       * still come — as a 409 at the end of a confirmation dialog, which is a
       * far worse place to learn it.
       */
      setProposedValue(proposalId: string, value: unknown): void {
        this.putProposalState(proposalId, {
          editedValue: value,
          edited: true,
          preview: null,
          previewOutcome: null,
          previewError: null,
          applyOutcome: null,
          applyError: null,
        });
      },

      /**
       * The overrides a preview or an apply travels with.
       *
       * Only sent when the value actually differs from the one the backend
       * proposed: an override that restates the proposal is noise in the audit
       * log, and the contract allows exactly two editable members.
       */
      proposalOverrides(
        signature: string,
        proposalId: string,
      ): Record<string, unknown> | null {
        const proposal = (this.changeProposals[signature] ?? []).find(
          (entry) => entry.proposal_id === proposalId,
        );
        const state = this.proposalStates[proposalId];
        if (!proposal || !state) return null;
        const same =
          JSON.stringify(state.editedValue ?? null) ===
          JSON.stringify(proposal.proposed_value ?? null);
        return same ? null : { proposed_value: state.editedValue };
      },

      /**
       * Dry-run one proposal. Persists nothing; returns the token Apply needs.
       */
      async previewChangeProposal(
        signature: string,
        proposalId: string,
      ): Promise<void> {
        const state = this.proposalStates[proposalId];
        if (!state || state.previewing) return;

        this.putProposalState(proposalId, {
          previewing: true,
          previewError: null,
          previewOutcome: null,
        });

        try {
          const result = await touchlessService.previewChangeProposal(
            proposalId,
            {
              issueSignature: signature,
              windowDays: TOUCHLESS_ADVICE_WINDOW_DAYS,
              overrides: this.proposalOverrides(signature, proposalId),
            },
          );
          if (result.outcome === 'ok') {
            this.putProposalState(proposalId, {
              previewing: false,
              preview: result,
              previewOutcome: 'ok',
              previewError: null,
              // The preview is now the value's dry run, so it is no longer an
              // unpreviewed edit.
              edited: false,
            });
            return;
          }
          this.putProposalState(proposalId, {
            previewing: false,
            preview: null,
            previewOutcome: result.outcome,
            previewError:
              result.message ?? `touchless_proposal_preview_${result.outcome}`,
          });
        } catch (error) {
          this.putProposalState(proposalId, {
            previewing: false,
            preview: null,
            previewOutcome: 'unavailable',
            previewError:
              messageFromError(error) ?? 'touchless_proposal_preview_failed',
          });
        }
      },

      /**
       * Write the setting, then read back what it was worth.
       *
       * Refused outright without a token — the button is disabled, but the
       * action is reachable by other means and this one changes a live tenant.
       */
      async applyChangeProposal(
        signature: string,
        proposalId: string,
      ): Promise<void> {
        const state = this.proposalStates[proposalId];
        if (!state || state.applying) return;
        const token = state.preview?.previewToken;
        if (!token || state.edited) {
          this.putProposalState(proposalId, {
            applyOutcome: 'needs_preview',
            applyError: 'touchless_proposal_apply_needs_preview',
          });
          return;
        }

        this.putProposalState(proposalId, {
          applying: true,
          applyError: null,
          applyOutcome: null,
        });

        try {
          const result = await touchlessService.applyChangeProposal(
            proposalId,
            {
              issueSignature: signature,
              windowDays: TOUCHLESS_ADVICE_WINDOW_DAYS,
              previewToken: token,
              overrides: this.proposalOverrides(signature, proposalId),
            },
          );

          if (result.outcome !== 'applied') {
            this.putProposalState(proposalId, {
              applying: false,
              applyOutcome: result.outcome,
              applyError:
                result.message ?? `touchless_proposal_apply_${result.outcome}`,
              // A refused apply has spent its token either way: the value may
              // have moved under us, so the dry run has to be repeated.
              preview: null,
            });
            return;
          }

          this.putProposalState(proposalId, {
            applying: false,
            applyOutcome: 'applied',
            applyError: null,
            changeId: result.changeId,
            // Spent. A second press must dry-run again.
            preview: null,
            reverted: false,
          });
          await this.refreshChangeOutcome(proposalId);
        } catch (error) {
          this.putProposalState(proposalId, {
            applying: false,
            applyOutcome: 'unavailable',
            applyError:
              messageFromError(error) ?? 'touchless_proposal_apply_failed',
            preview: null,
          });
        }
      },

      /**
       * Re-read the measured effect of an applied change.
       *
       * Never invents one: under the minimum sample the server answers "not
       * yet measurable" with the `n` it judged against, and that is what the
       * badge says.
       */
      async refreshChangeOutcome(proposalId: string): Promise<void> {
        const changeId = this.proposalStates[proposalId]?.changeId;
        if (!changeId) return;
        try {
          const outcome = await touchlessService.getChangeOutcome(
            changeId,
            TOUCHLESS_ADVICE_WINDOW_DAYS,
          );
          this.putProposalState(proposalId, { outcome });
        } catch (error) {
          logger.warn('[Touchless] change outcome unreadable', error);
        }
      },

      /**
       * Put back the value the setting held before the change.
       *
       * The server restores its own stored `current_value`; nothing here
       * computes it from the applied one.
       */
      async revertChangeProposal(proposalId: string): Promise<void> {
        const state = this.proposalStates[proposalId];
        if (!state?.changeId || state.reverting) return;

        this.putProposalState(proposalId, {
          reverting: true,
          applyError: null,
        });
        try {
          const result = await touchlessService.revertChangeOutcome(
            state.changeId,
          );
          if (result.outcome !== 'reverted') {
            this.putProposalState(proposalId, {
              reverting: false,
              applyError:
                result.message ?? `touchless_proposal_revert_${result.outcome}`,
            });
            return;
          }
          this.putProposalState(proposalId, {
            reverting: false,
            reverted: true,
            changeId: null,
            outcome: null,
            applyOutcome: null,
          });
        } catch (error) {
          this.putProposalState(proposalId, {
            reverting: false,
            applyError:
              messageFromError(error) ?? 'touchless_proposal_revert_failed',
          });
        }
      },

      /** Forget every proposal and its state — panel teardown, filter change. */
      resetChangeProposals(): void {
        this.changeProposals = {};
        this.changeProposalsLoading = {};
        this.changeProposalsError = {};
        this.proposalStates = {};
      },
    },
  },
);

/** Best available wording for a thrown API failure, or null. */
function messageFromError(error: unknown): string | null {
  if (typeof error === 'string' && error.trim()) return error;
  if (error && typeof error === 'object') {
    const candidate = error as Record<string, unknown>;
    for (const key of ['message', 'detail'] as const) {
      const value = candidate[key];
      if (typeof value === 'string' && value.trim()) return value;
    }
  }
  return null;
}
